<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { MessageCircle, Send, Users, X, ChevronDown } from 'lucide-vue-next';
const props=defineProps({user:{type:Object,default:null}});
const emit=defineEmits(['enter','login']);
const open=ref(false), messages=ref([]), draft=ref(''), busy=ref(false), error=ref(''), toast=ref(''), list=ref(null), connected=ref(true), serviceMissing=ref(false);
let stopped=false, pollTimer, toastTimer, reading=false, epoch='', lastId=0, initialized=false, pendingText=null, pendingInvite=null;
function key(){return globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}_${Math.random().toString(36).slice(2)}_${Math.random().toString(36).slice(2)}`}
async function request(path, body){let response;try{response=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(8000),cache:'no-store'});}catch{throw new Error('连接失败，请检查网络后重试');}const data=await response.json().catch(()=>({}));if(!response.ok)throw Object.assign(new Error(data.message||'请求失败'),{status:response.status});return data;}
function schedule(){clearTimeout(pollTimer);if(!stopped)pollTimer=setTimeout(refresh,document.hidden?10000:3000+Math.random()*1000)}
async function refresh(){if(stopped||reading||!props.user){schedule();return}reading=true;try{const data=await request('/api/lobby/messages');const fresh=initialized&&epoch===data.epoch?data.messages.filter(m=>m.id>lastId&&m.userId!==props.user.id):[];const nearBottom=list.value && list.value.scrollHeight-list.value.scrollTop-list.value.clientHeight<80;messages.value=data.messages||[];connected.value=true;serviceMissing.value=false;epoch=data.epoch;lastId=messages.value.at(-1)?.id||0;initialized=true;if(!open.value&&fresh.length){const m=fresh.at(-1);toast.value=m.type==='invite'?`${m.name} 发起了组队邀请`:`${m.name}：${m.text}`;clearTimeout(toastTimer);if(!document.hidden)toastTimer=setTimeout(()=>{toast.value=''},5000)}if(open.value&&nearBottom)nextTick(scrollBottom);}catch(e){ connected.value=false;serviceMissing.value=e.status===404; /* keep existing messages until the next check */ }finally{reading=false;schedule()}}
function scrollBottom(){if(list.value)list.value.scrollTop=list.value.scrollHeight}
function expand(){if(!props.user){emit('login');return}open.value=!open.value;if(open.value){toast.value='';refresh();nextTick(scrollBottom)}}
async function send(){if(!props.user){emit('login');return}const text=draft.value.trim();if(!text||busy.value)return;busy.value=true;error.value='';if(!pendingText||pendingText.text!==text)pendingText={text,requestId:key()};try{await request('/api/lobby/messages',pendingText);if(draft.value.trim()===text)draft.value='';pendingText=null;await refresh();nextTick(scrollBottom)}catch(e){error.value=e.message;if(e.status&&e.status<500)pendingText=null}finally{busy.value=false}}
async function invite(mode){if(!props.user){emit('login');return}if(busy.value)return;busy.value=true;error.value='';if(!pendingInvite||pendingInvite.mode!==mode)pendingInvite={mode,requestId:key()};try{const data=await request('/api/lobby/invitations',pendingInvite);pendingInvite=null;emit('enter',data.mode)}catch(e){error.value=e.message;if(e.status&&e.status<500)pendingInvite=null}finally{busy.value=false}}
async function join(item){if(!props.user){emit('login');return}if(busy.value)return;busy.value=true;error.value='';try{const data=await request(`/api/lobby/invitations/${item.id}/join`,{epoch:item.epoch});emit('enter',data.mode)}catch(e){error.value=e.message;await refresh()}finally{busy.value=false}}
function visible(){if(!document.hidden){if(toast.value){clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast.value=''},5000)}refresh()}}
onMounted(()=>{refresh();document.addEventListener('visibilitychange',visible)});onBeforeUnmount(()=>{stopped=true;clearTimeout(pollTimer);clearTimeout(toastTimer);document.removeEventListener('visibilitychange',visible)});watch(()=>props.user?.id,()=>{epoch='';lastId=0;initialized=false;messages.value=[];refresh()});
</script>
<template>
 <aside class="lobby-chat" :class="{expanded:open}" aria-label="组队聊天">
  <button v-if="toast&&!open" type="button" class="lobby-toast" @click="expand">{{toast}}</button>
  <button v-if="!open" type="button" class="chat-launch" @click="expand"><MessageCircle :size="18"/> 组队聊天</button>
  <section v-else class="chat-panel"><header><div><strong>组队聊天</strong><small>邀请同学一起玩</small></div><button type="button" aria-label="收起聊天" @click="open=false"><ChevronDown :size="20"/></button></header>
   <div ref="list" class="chat-messages" aria-live="polite"><p v-if="!connected" class="chat-connection" role="status">{{serviceMissing ? '教师机服务需要更新，请联系老师重启。' : '暂时无法连接，正在重试。'}}</p><p v-if="connected && !messages.length" class="chat-empty">还没有消息，发起邀请找同学一起玩。</p><article v-for="item in messages" :key="item.id" class="chat-message"><div class="chat-meta"><strong>{{item.name}}</strong><time>{{new Date(item.createdAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}}</time></div><p v-if="item.type==='text'">{{item.text}}</p><div v-else class="invite-card"><div><b>{{({race:'打字赛车',chase:'生死时速',rhythm:'字母音游',boss:'极速淘汰赛',battle:'阵营对抗'})[item.mode] || '组队邀请'}}</b><small v-if="item.room">{{item.room.count}} / {{item.room.capacity}} 人 · {{item.room.phase==='waiting'?'等待加入':item.room.phase==='running'?'进行中':'已开始'}}</small><small v-else>房间已关闭</small><small v-if="item.mode==='battle'">加入同一对局，阵营自动平衡</small></div><button type="button" :disabled="busy||!item.canJoin" @click="join(item)">{{item.userId===user?.id?'进入房间':item.canJoin?'加入房间':'不可加入'}}</button></div></article></div>
   <div class="chat-compose"><div class="chat-invites"><span>一键邀请</span><button type="button" :disabled="busy" @click="invite('race')">赛车</button><button type="button" :disabled="busy" @click="invite('chase')">生死时速</button><button type="button" :disabled="busy" @click="invite('rhythm')">音游</button><button type="button" :disabled="busy" @click="invite('boss')">淘汰赛</button><button type="button" :disabled="busy" @click="invite('battle')">阵营对抗</button></div><p v-if="error" class="chat-error" role="alert">{{error}}</p><form @submit.prevent="send"><input v-model="draft" maxlength="200" placeholder="说点什么…" aria-label="聊天消息"/><button type="submit" :disabled="busy||!draft.trim()" aria-label="发送消息"><Send :size="17"/></button></form></div>
  </section>
 </aside>
</template>
<style scoped>
.lobby-chat{position:fixed;right:22px;bottom:20px;z-index:80;font-family:inherit}.chat-launch{display:flex;align-items:center;gap:8px;border:0;border-radius:99px;background:#287bdd;color:#fff;padding:12px 18px;box-shadow:0 8px 24px #275c9638;cursor:pointer;font-weight:700}.lobby-toast{position:absolute;right:0;bottom:58px;width:max-content;max-width:min(320px,85vw);padding:11px 14px;border:1px solid #d7e5f6;border-radius:12px;background:white;color:#284c70;box-shadow:0 8px 26px #153e6026;cursor:pointer;overflow-wrap:anywhere}.chat-panel{display:flex;flex-direction:column;width:min(360px,calc(100vw - 24px));height:min(520px,calc(100dvh - 40px));background:#fff;border:1px solid #d8e5f3;border-radius:16px;box-shadow:0 16px 50px #153e6033;overflow:hidden}.chat-panel header{display:flex;align-items:center;justify-content:space-between;padding:15px 17px;background:#eff6ff;border-bottom:1px solid #dfeaf7;color:#23466c}.chat-panel header strong,.chat-panel header small{display:block}.chat-panel header small{font-size:12px;color:#7e97b0;margin-top:3px}.chat-panel header button{border:0;background:transparent;color:#557999;cursor:pointer}.chat-messages{flex:1;min-height:0;overflow-y:auto;padding:14px 16px}.chat-connection{color:#a76410;font-size:12px}.chat-empty{color:#8299af;text-align:center;font-size:13px;margin:40px 0}.chat-message{margin-bottom:16px}.chat-meta{display:flex;gap:9px;align-items:center;font-size:12px;color:#8ba0b2}.chat-meta strong{color:#345d80}.chat-message p{margin:6px 0;white-space:pre-wrap;overflow-wrap:anywhere;color:#284661;font-size:14px}.invite-card{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:7px;padding:12px;background:#f2f7fd;border:1px solid #dceafa;border-radius:10px}.invite-card b,.invite-card small{display:block}.invite-card small{margin-top:4px;color:#7890a5;font-size:12px}.invite-card button,.chat-invites button{border:0;border-radius:7px;padding:7px 10px;background:#347ed2;color:white;cursor:pointer}.invite-card button:disabled,.chat-invites button:disabled{opacity:.45;cursor:not-allowed}.chat-compose{padding:12px 14px;border-top:1px solid #e6eef7}.chat-invites{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:12px;color:#728aa1}.chat-invites button{background:#edf5ff;color:#286bb4}.chat-compose form{display:flex;gap:7px;margin-top:10px}.chat-compose input{flex:1;min-width:0;border:1px solid #dbe7f2;border-radius:8px;padding:9px;outline-color:#77adeb}.chat-compose form button{width:38px;border:0;border-radius:8px;background:#347ed2;color:white;cursor:pointer}.chat-compose form button:disabled{opacity:.45}.chat-error{color:#b94141;font-size:12px;margin:8px 0 0}@media(max-width:600px){.lobby-chat{right:12px;bottom:12px}}
</style>
